using System;
using System.Collections.Generic;
using System.Linq;
using Comfort.Common;
using EFT;
using EFT.InventoryLogic;
using UnityEngine;
namespace LocalSpt5Esp;
internal static partial class RaidCommands {
 static Slot[] InventorySlots(Player p){var equipment=p.Profile?.Inventory?.Equipment??throw new ArgumentException("装备未就绪。");var result=new List<Slot>();foreach(var kind in Enum.GetValues<EquipmentSlot>()){var slot=equipment.GetSlot(kind);if(slot!=null)result.Add(slot);}return result.ToArray();}
 static Slot Slot(Player p,string name){if(!Enum.TryParse<EquipmentSlot>(name,true,out var kind)||!Enum.IsDefined(kind))throw new ArgumentException("未知装备槽；Tab 补全。");return p.Profile?.Inventory?.Equipment?.GetSlot(kind)??throw new ArgumentException("装备槽不可用。");}
 static ItemFactory Factory()=>Singleton<ItemFactory>.Instance??throw new ArgumentException("物品工厂未就绪。");
 static string Template(string value)=>ItemSpawner.CommandItems.Resolve(value);
 static Item BuildItem(string template,int count){var factory=Factory();var item=factory.CreateItem(factory.NextId.ToString(),template,null)??throw new ArgumentException("物品创建失败。");if(count>Math.Max(1,item.StackMaxSize))throw new ArgumentException("数量超过单个堆叠容量。");item.StackObjectsCount=count;item.SpawnedInSession=true;return item;}
 static int Give(Player p,string template,int count){var controller=p.InventoryController??throw new ArgumentException("库存控制器未就绪。");int added=0;for(int n=0;n<100&&added<count;n++){var item=BuildItem(template,1);item.StackObjectsCount=Math.Min(count-added,Math.Max(1,item.StackMaxSize));ItemAddress? destination=null;
  foreach(var slot in InventorySlots(p).OrderBy(s=>s.Name=="Backpack"?0:s.Name=="TacticalVest"?1:2)){var container=slot.ContainedItem?.TryCast<CompoundItem>();if(container?.Grids==null)continue;foreach(var grid in container.Grids){if(grid==null)continue;var candidate=grid.FindLocationForItem(item);if(candidate!=null&&ItemManipulator.Add(item,candidate,controller,true).Succeeded){destination=candidate;break;}}if(destination!=null)break;}
  if(destination==null)foreach(var slot in InventorySlots(p)){if(slot.ContainedItem!=null)continue;var candidate=slot.CreateItemAddress();if(ItemManipulator.Add(item,candidate,controller,true).Succeeded){destination=candidate;break;}}
  if(destination==null)break;controller.AddAndRaiseEvents(item,destination);if(item.CurrentAddress==null)break;added+=item.StackObjectsCount;
 }p.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);return added;}
 static Item[] InventoryItems(Player p){var result=new List<Item>();var seen=new HashSet<IntPtr>();void Visit(Item item,int depth){if(depth>16||!seen.Add(item.Pointer))return;result.Add(item);foreach(var child in LootDisplay.Children(item))Visit(child,depth+1);}foreach(var slot in InventorySlots(p))if(slot.ContainedItem!=null)Visit(slot.ContainedItem,0);return result.ToArray();}
 static void RemoveItem(Player p,Item item){var controller=p.InventoryController??throw new ArgumentException("库存控制器未就绪。");var result=ItemManipulator.Remove(item,controller,false);if(!result.Succeeded)throw new ArgumentException("游戏拒绝移除正在使用的物品或必需附件。");result.Value.RaiseEvents(controller.Cast<IItemOwner>(),CommandStatus.Succeed);}
 static void ApplyLoadout(GameWorld w,Player actor,AiBirthPreset preset){if(preset.Equipment==null)throw new ArgumentException("模板没有装备方案。");foreach(var pair in preset.Equipment){if(pair.Value==null)continue;var slot=Slot(actor,pair.Key);if(AiWeaponSlotRules.Allowed(pair.Key)){AiSceneEquipment.Enqueue(w,actor,pair.Value,Enum.Parse<EquipmentSlot>(pair.Key),false,"聊天装备方案");continue;}if(slot.ContainedItem!=null)throw new ArgumentException("非武器装备槽需先清空；已提交的换枪队列不会自动回滚。");var tree=pair.Value;var item=BuildItem(tree.Template,1);tree.Parameters.Apply(item);ItemAttachments.Apply(item,Factory(),tree);var controller=actor.InventoryController;if(!ItemManipulator.Add(item,slot.CreateItemAddress(),controller,true).Succeeded)throw new ArgumentException("装备过滤器拒绝方案物品。");controller.AddAndRaiseEvents(item,slot.CreateItemAddress());}}
 static void Inventory(GameWorld w,string name,string[] a){switch(name){
  case "give":Require(a,2);string template=Template(a[1]);int count=a.Length>2?(int)ChatCommandSyntax.Number(a[2],1,100000):1;foreach(var p in Resolve(w,a[0])){int added=Give(p,template,count);RaidChat.Output(Name(p)+" 已添加 "+added+"/"+count+"；空间不足时停止，不自动重试。");}return;
  case "clear":Require(a,1);string? match=a.Length>1?Template(a[1]):null;int maximum=a.Length>2?(int)ChatCommandSyntax.Number(a[2],0,100000):100000;foreach(var p in Resolve(w,a[0])){var items=InventoryItems(p).Reverse().Where(item=>match==null||item.TemplateId==match).ToArray();if(maximum==0){RaidChat.Output(Name(p)+" 匹配数量 "+items.Sum(i=>(long)i.StackObjectsCount));continue;}int removed=0;foreach(var item in items){if(removed>=maximum)break;if(item.StackObjectsCount>maximum-removed){int amount=maximum-removed;item.StackObjectsCount-=amount;removed+=amount;}else{int amount=item.StackObjectsCount;RemoveItem(p,item);removed+=amount;}}p.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);RaidChat.Output(Name(p)+" 已移除 "+removed+" 件；包含容器时同时移除内部物品。");}return;
  case "item":ItemCommand(w,a);return;
  case "loot":Require(a,1);if(a[0]=="spawn"){Require(a,5);Vector3 point=Coordinates(w,a[1..4]);string id=Template(a[4]);int left=a.Length>5?(int)ChatCommandSyntax.Number(a[5],1,100000):1;var sample=BuildItem(id,1);if(left>32L*Math.Max(1,sample.StackMaxSize))throw new ArgumentException("单次最多32个堆叠。");int placed=0;while(left>0){int amount=Math.Min(left,Math.Max(1,sample.StackMaxSize));var item=BuildItem(id,amount);w.ThrowItem(item,w.MainPlayer.Cast<IPlayer>(),point+Vector3.up*(.15f+placed*.03f),Quaternion.identity,Vector3.zero,Vector3.zero,true,true,0);left-=amount;placed++;}RaidChat.Output("已生成物资堆叠 ×"+placed);return;}if(a[0]=="give"){Require(a,3);if(!a[2].StartsWith("loadout:",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("/loot give <目标> loadout:<场景名>");var scene=SceneTemplates.ChatTemplate(a[2][8..]);foreach(var p in Ai(w,a[1]))ApplyLoadout(w,p,scene.Birth);RaidChat.Output("已应用 AI 装备方案。");return;}throw new ArgumentException("/loot spawn <x y z> <物品> [数量] | give <AI> loadout:<场景名>");
  case "repair":Require(a,1);foreach(var p in Resolve(w,a[0])){var items=a.Length>1?new[]{Slot(p,a[1]).ContainedItem??throw new ArgumentException("槽位为空。")}:InventoryItems(p);int repaired=0;foreach(var item in items){var repair=item.GetItemComponent<RepairableComponent>();if(repair==null)continue;repair.Durability=repair.MaxDurability;repaired++;}p.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);RaidChat.Output(Name(p)+" 已修复 "+repaired+" 件装备至当前最大耐久。");}return;
  case "reload":Reload(w,a);return;
 }}
 static void ItemCommand(GameWorld w,string[] a){Require(a,5);if(a[1]!="entity")throw new ArgumentException("仅支持 item ... entity。");var targets=Resolve(w,a[2]);if(a[0]=="replace"){Require(a,6);if(a[4]!="with")throw new ArgumentException("/item replace entity <目标> <槽> with <物品> [数量]");string template=Template(a[5]);int count=a.Length>6?(int)ChatCommandSyntax.Number(a[6],1,100000):1;
  // All targets and item compatibility are checked before any replacement.
  var plans=targets.Select(p=>{var slot=Slot(p,a[3]);var item=BuildItem(template,count);var controller=p.InventoryController??throw new ArgumentException("库存未就绪。");if(slot.ContainedItem!=null)throw new ArgumentException("安全替换要求槽位为空。先 /clear 该物品；不会静默销毁旧装备。");if(!ItemManipulator.Add(item,slot.CreateItemAddress(),controller,true).Succeeded)throw new ArgumentException("原生装备过滤器拒绝此物品。");return (Player:p,Slot:slot,Item:item);}).ToArray();foreach(var plan in plans){plan.Player.InventoryController.AddAndRaiseEvents(plan.Item,plan.Slot.CreateItemAddress());if(plan.Slot.ContainedItem?.Pointer!=plan.Item.Pointer)throw new ArgumentException("装备回读失败；之前完成的对象不会自动回滚。");plan.Player.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);}RaidChat.Output("已添加装备至空槽位 ×"+plans.Length);return;
 }if(a[0]!="modify"||a.Length!=6)throw new ArgumentException("/item modify entity <目标> <槽> <参数> <值>");var settings=new ItemComponentParameters();float Number()=>(float)ChatCommandSyntax.Number(a[5],0,float.MaxValue);switch(a[4]){case "durability":settings.Durability=Number();break;case "maxDurability":settings.MaxDurability=Number();break;case "medicalResource":settings.MedicalResource=Number();break;case "foodResource":settings.FoodResource=Number();break;case "keyRemaining":settings.KeyRemaining=(int)ChatCommandSyntax.Number(a[5],0,int.MaxValue);break;case "poisonUses":settings.PoisonUses=Number();break;case "resource":settings.Resource=Number();break;case "repairKitResource":settings.RepairKitResource=Number();break;case "toggledOn":settings.ToggledOn=Boolean(a[5]);break;case "foundInRaid":settings.FoundInRaid=Boolean(a[5]);break;default:throw new ArgumentException("不支持的物品参数。");}foreach(var p in targets){var item=Slot(p,a[3]).ContainedItem??throw new ArgumentException("装备槽为空。");settings.Apply(item);p.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);}RaidChat.Output("物品参数已更新。");}
}
